import json
import re
import sys

# O passo "python" do sandbox roda com -I (modo isolado), que ignora o
# site-packages do usuario (no Windows o pip costuma instalar la:
# AppData\Roaming\Python\PythonXY\site-packages). Sem isto, "import ddgs"
# falharia mesmo depois de "pip install ddgs".
try:
    import site

    _user_site = site.getusersitepackages()
    if _user_site and _user_site not in sys.path:
        sys.path.append(_user_site)
except Exception:
    pass


def emit(payload):
    print(json.dumps(payload, ensure_ascii=False))


def clean_query(text):
    text = str(text or "").strip()
    text = re.sub(r"^\s*(?:astra[,\s]+)?(?:por favor[,\s]+)?", "", text, flags=re.I)
    text = re.sub(
        r"^\s*(?:pesquis(?:e|ar|a)|busc(?:ue|ar|a)|procur(?:e|ar|a)|consult(?:e|ar))\s+"
        r"(?:por\s+|sobre\s+|acerca de\s+|a respeito de\s+)?",
        "",
        text,
        flags=re.I,
    )
    text = re.sub(
        r"\s+(?:no|na|pelo|pela)\s+(?:duck\s*duck\s*go|internet|web|google)\b.*$",
        "",
        text,
        flags=re.I,
    )
    return text.strip(" .,:;!?\t\r\n")


def shorten(value, limit):
    value = re.sub(r"\s+", " ", str(value or "")).strip()
    return value if len(value) <= limit else value[: limit - 1].rstrip() + "…"


def main():
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except Exception:
        payload = {}

    query = clean_query(payload.get("query")) or clean_query(payload.get("context"))
    try:
        max_results = max(1, min(int(payload.get("max_results", 5)), 8))
    except Exception:
        max_results = 5

    if not query:
        emit({"ok": False, "error": "Nenhum assunto informado para pesquisar."})
        return

    try:
        try:
            from ddgs import DDGS
        except ImportError:
            from duckduckgo_search import DDGS  # nome antigo do pacote
    except ImportError:
        emit(
            {
                "ok": False,
                "query": query,
                "error": "Pacote ddgs nao instalado. Rode: python -m pip install ddgs",
            }
        )
        return

    # Olha o pedido original inteiro: o sandbox ja tira "sobre ..." do assunto,
    # e com isso palavras como "noticias" podem nao estar mais em `query`.
    full_request = f"{payload.get('context', '')} {query}"
    wants_news = bool(re.search(r"\b(not[ií]cias?|news|[uú]ltimas|[uú]ltimos)\b", full_request, re.I))
    attempts = (["news"] if wants_news else []) + ["text"]

    results = []
    kind = "text"
    last_error = None
    client = DDGS()

    for mode in attempts:
        for region in ("br-pt", "wt-wt"):
            try:
                if mode == "news":
                    raw = list(client.news(query, region=region, max_results=max_results))
                else:
                    raw = list(client.text(query, region=region, max_results=max_results))
            except Exception as exc:
                last_error = str(exc)
                continue

            for item in raw:
                title = shorten(item.get("title"), 160)
                if not title:
                    continue
                entry = {
                    "title": title,
                    "url": str(item.get("href") or item.get("url") or "").strip(),
                    "snippet": shorten(item.get("body"), 300),
                }
                if item.get("date"):
                    entry["date"] = str(item["date"])
                if item.get("source"):
                    entry["source"] = shorten(item["source"], 60)
                results.append(entry)

            if results:
                kind = mode
                break
        if results:
            break

    if results:
        emit({"ok": True, "query": query, "kind": kind, "results": results[:max_results]})
    else:
        emit(
            {
                "ok": False,
                "query": query,
                "error": last_error or "Nenhum resultado encontrado.",
            }
        )


main()
